import './local-api.js';
import './cloud-api.js';

// One document, one navigation, and the existing Supabase schema.
const pristine='<!DOCTYPE html>'+document.documentElement.outerHTML;
const A=JSON.parse(document.getElementById('portfolio-assets').textContent);
const cloud=window.portfolioCloud;
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeGet=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}};
const safeSet=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
const paths={arrow:'M7 17 17 7M7 7h10v10',right:'M4 12h16m-6-6 6 6-6 6',folder:'M3 7V5h6l2 3h10v12H3z',user:'M20 21v-2a7 7 0 0 0-14 0v2M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10',cap:'m2 8 10-5 10 5-10 5-10-5m4 3v6c4 3 8 3 12 0v-6m4-3v8',chart:'M4 20V4m0 16h17M8 16v-4m5 4V8m5 8V5',bell:'M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10m-9 13h6',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4m-4 5v2',cloud:'M7 18a5 5 0 1 1 .4-10 7 7 0 0 1 13.2 3A4 4 0 0 1 20 19H7',check:'m5 12 4 4L19 6',refresh:'M20 7a8 8 0 0 0-14-1L3 9m0-6v6h6m-5 8a8 8 0 0 0 14 1l3-3m0 6v-6h-6',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',download:'M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4',edit:'m15 4 5 5M4 20l5-1L21 7l-4-4L5 15z',trash:'M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 13h8m-8 4h6',code:'m8 5-7 7 7 7m8-14 7 7-7 7M14 3l-4 18',database:'M20 5c0 4-16 4-16 0s16-4 16 0M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',game:'M7 7h10c3 0 5 9 4 12-1 3-5-3-6-3H9c-1 0-5 6-6 3C2 16 4 7 7 7zm-2 5h6m-3-3v6m8-4h.01m2 3h.01',book:'M12 5C9 2 5 2 2 3v17c3-1 7-1 10 2m0-17c3-3 7-3 10-2v17c-3-1-7-1-10 2V5',time:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6l4 2',eye:'M2 12c5-10 15-10 20 0-5 10-15 10-20 0m10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',mail:'M3 5h18v14H3zM3 5l9 8 9-8',star:'m12 2 3 7 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1z',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',logout:'M9 3H3v18h6m5-15 6 6-6 6m-5-6h11',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',volume:'M4 9h4l5-5v16l-5-5H4zm12-3c4 3 4 9 0 12m3-15c6 5 6 13 0 18',send:'m2 3 20 9-20 9 4-9-4-9m4 9h16',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 7v7m0-10v.1',pause:'M8 4v16m8-16v16',play:'m7 3 14 9-14 9z',history:'M3 4v6h6M4 8a9 9 0 1 1 0 8m8-10v6l4 2',globe:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20m0 0c-5 6-5 14 0 20m0-20c5 6 5 14 0 20M2 12h20'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const button=(text,act,ic='',kind='',attrs='')=>`<button type="button" class="btn ${kind}" data-action="${act}" ${attrs}>${ic?icon(ic):''}${text}</button>`;
const link=(text,route,kind='')=>`<a class="btn ${kind}" href="#${route}">${text}${icon('arrow')}</a>`;
const title=(num,text,desc)=>`<div class="page-title"><div class="eyebrow">${num} / BITÁCORA DE YUBER</div><h1>${text}</h1><p>${desc}</p></div>`;
const notice=(text)=>`<div class="notice">${icon('info')}<span>${text}</span></div>`;
const units=['Fundamentos y diseño','Consultas y programación','Gestión y optimización','Integración y proyecto'];
const routes={inicio:'Inicio',perfil:'Sobre mí',universidad:'Universidad',trabajos:'Trabajos',progreso:'Progreso',recursos:'Recursos',cuenta:'Mi cuenta',notificaciones:'Notificaciones'};
const defaultProfile={name:'Yuber',code:'T04128B',career:'Ingeniería de Sistemas',university:'Universidad Peruana Los Andes',bio:'Soy Yuber, estudiante de Ingeniería de Sistemas en la Universidad Peruana Los Andes. Me interesa comprender cómo los datos se convierten en soluciones útiles, combinar la lógica con la creatividad y aprender construyendo.',purpose:'Comprender cómo funcionan los datos y usarlos para crear soluciones útiles.',motivation:'Unir pensamiento lógico y creatividad para resolver problemas mediante la tecnología.',learning:'Aprender construyendo, revisar mis errores y mejorar una evidencia a la vez.',goal:'Desarrollar proyectos que conecten lo que aprendo con problemas reales.',cycle:''};
let embeddedProfile={};try{embeddedProfile=JSON.parse($('#portfolio-presentation').textContent);}catch{}
const state={route:'inicio',theme:safeGet('yuber-theme-v2','jjk'),profile:{...defaultProfile,...embeddedProfile,...safeGet('yuber-presentation-v2',{})},works:[],admin:false,unit:1,week:1,search:'',filter:'all',allWeeks:false,busy:false,guest:false,loaded:false,chat:[],paused:safeGet('yuber-paused',false)};
if(!['jjk','game'].includes(state.theme))state.theme='jjk';
const offline=!cloud.getState().configured;
const authenticated=()=>offline||!!cloud.getState().role;
const readOnly=()=>state.admin;
const fmtBytes=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':n>=1024?(n/1024).toFixed(1)+' KB':n+' B';
const fmtDate=s=>s?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium'}).format(new Date(s)):'—';
const metrics=()=>{const slots=new Set(state.works.map(w=>`${w.unit}-${w.week}-${w.day}`)).size;const graded=state.works.filter(w=>w.grade!==null&&w.grade!==undefined);return {slots,percent:Math.round(slots/32*100),graded,average:graded.length?(graded.reduce((s,w)=>s+w.grade,0)/graded.length).toFixed(1):'—'};};
const themeSwitch=()=>`<div class="theme-switch" role="group" aria-label="Tema visual"><button data-action="theme" data-theme="jjk" aria-pressed="${state.theme==='jjk'}" class="${state.theme==='jjk'?'active':''}">${icon('spark')}Jujutsu Kaisen</button><button data-action="theme" data-theme="game" aria-pressed="${state.theme==='game'}" class="${state.theme==='game'?'active':''}">${icon('game')}Videojuego</button></div>`;
function frame(){
 $('#app').innerHTML=`<header class="site-header"><div class="header-inner"><a class="brand" href="#inicio" aria-label="Bitácora de Yuber, inicio"><img src="${A.upla}" alt="Logo UPLA"><div><strong>bitácora<b>.</b></strong><small>BASE DE DATOS II</small></div></a><nav class="nav" aria-label="Navegación principal">${Object.entries(routes).slice(0,6).map(([id,label])=>`<a href="#${id}" data-route="${id}">${label}</a>`).join('')}</nav><div class="head-actions"><button class="icon-btn notify-btn" data-action="notifications" aria-label="Notificaciones">${icon('bell')}<i class="dot" id="notify-dot" hidden></i></button><button class="avatar-btn" data-action="account" aria-label="Mi cuenta"><img src="${A.photo}" alt="Yuber"><span id="account-label">Mi cuenta<small>Iniciar sesión</small></span></button><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menú" aria-expanded="false">${icon('menu')}</button></div></div></header><main id="main" class="main-shell" tabindex="-1"></main><footer class="site-footer"><div class="footer-brand"><img src="${A.upla}" alt=""><span>Yuber · Ingeniería de Sistemas<br>Universidad Peruana Los Andes</span></div><div class="footer-actions"><button data-action="account">Mi cuenta</button><button data-action="export">Descargar HTML</button><button data-action="motion" id="motion-label">${state.paused?'Reanudar':'Pausar'} animaciones</button><a href="#recursos">Ayuda</a></div></footer>`;
}
function render(){
 if(!routes[state.route])state.route='inicio';
 const views={inicio:home,perfil:profile,universidad:university,trabajos:worksPage,progreso:progress,recursos:resources,cuenta:account,notificaciones:notifications};
 $('#main').innerHTML=`<div class="page"><div class="topline"><div class="crumb">UPLA<span>/</span>Mi portafolio<span>/</span>${routes[state.route]}</div>${themeSwitch()}</div>${views[state.route]()}</div>`;
 $$('.nav a').forEach(a=>{const active=a.dataset.route===state.route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 updateStatus();applyTheme();if(state.route==='trabajos')renderWorks();
}
function goto(route){if(location.hash==='#'+route){state.route=route;render();window.scrollTo({top:0,behavior:'instant'});}else location.hash=route;}
function stats(){const m=metrics();return `<div class="stats"><div class="stat"><strong>04</strong><span>Unidades de aprendizaje</span></div><div class="stat"><strong>16</strong><span>Semanas para construir</span></div><div class="stat"><strong><em data-stat="works">${authenticated()?state.works.length:'—'}</em></strong><span>Trabajos guardados</span></div><div class="stat"><strong data-stat="progress">${authenticated()?m.percent+'%':'—'}</strong><span>Sesiones con evidencias</span></div></div>`;}
function world(){return `<section class="world"><img data-world-art src="${A[state.theme]}" alt="${state.theme==='jjk'?'Gojo y Yuji, ilustración de Jujutsu Kaisen':'Consolas, control y personajes de videojuego'}"><div class="world-copy"><div class="eyebrow" data-world-label>${state.theme==='jjk'?'EDICIÓN / JUJUTSU KAISEN':'EDICIÓN / PLAYER ONE'}</div><h2 data-world-title>${state.theme==='jjk'?'Enfocar. Crear.<br>Superar mis límites.':'El siguiente nivel<br>lo construyo yo.'}</h2><p>Dos universos, una misma historia. Mi forma de aprender también tiene personalidad.</p><div class="btn-row">${button('Cambiar universo','swap-theme','spark','small')}</div></div><div class="world-code" data-world-code>${state.theme==='jjk'?'CURSED ENERGY / 01':'PRESS START / 02'}</div></section>`;}
function actionCard(ic,name,desc,route,label){return `<a class="panel action" href="#${route}"><span class="tile-icon">${icon(ic)}</span><span class="corner">${icon('arrow')}</span><h3>${name}</h3><p>${desc}</p><span class="panel-link">${label||'Explorar'}${icon('right')}</span></a>`;}
function home(){return `<section class="hero"><div><span class="badge accent"><i class="dot"></i>ESTUDIANTE UPLA · INGENIERÍA DE SISTEMAS</span><h1>Soy ${esc(state.profile.name)}.<br>Aprendo, creo<br>y <em>evoluciono.</em></h1><p>Un espacio para mi historia, mis ideas y todo lo que construyo en <strong style="color:var(--ink)">Base de Datos II</strong>. Cada trabajo es un nuevo paso en mi formación.</p><div class="btn-row">${link('Explorar mis trabajos','trabajos','primary')}${link('Conóceme','perfil','quiet')}</div><div class="hero-note">${icon('database')}De la curiosidad a las soluciones. Una evidencia a la vez.</div></div><div class="portrait"><div class="portrait-ring"></div><div class="portrait-frame"><img src="${A.photo}" alt="Foto de perfil de Yuber"><div class="portrait-caption"><div><strong>${esc(state.profile.name)}</strong><small>${esc(state.profile.code)} · UPLA</small></div>${icon(state.theme==='jjk'?'spark':'game')}</div></div><div class="portrait-stamp">EN CONSTRUCCIÓN<b>Mi mejor versión</b></div><div class="portrait-label">${icon('code')}Ideas que se vuelven proyectos</div></div></section>${stats()}<section class="section"><div class="section-head"><div><div class="eyebrow">MI MUNDO, EN UN SOLO LUGAR</div><h2>Más que una colección<br>de trabajos.</h2></div><p>Mi recorrido, mi universidad y las evidencias que dan forma a lo que aprendo.</p></div><div class="grid-3">${actionCard('user','La persona detrás','Mi presentación, mis intereses y lo que me motiva a seguir aprendiendo.','perfil','Leer mi historia')}${actionCard('cap','Mi vida académica','La UPLA, Ingeniería de Sistemas y el lugar de Base de Datos II en mi formación.','universidad','Conocer mi universidad')}${actionCard('chart','Cada paso cuenta','Entregas, revisiones y un progreso calculado con mis evidencias reales.','progreso','Ver mi recorrido')}</div></section>${world()}<section class="section"><div class="section-head"><div><div class="eyebrow">DEL APRENDIZAJE A LA PRÁCTICA</div><h2>Mis últimas evidencias.</h2></div>${link('Ver todos los trabajos','trabajos','small quiet')}</div><div id="recent-works">${recent()}</div></section>`;}
function recent(){if(!authenticated())return `<div class="empty">${icon('lock')}<h3>Tu cuenta, tus trabajos.</h3><p>Inicia sesión para consultar las entregas guardadas, también desde otro dispositivo.</p>${button('Iniciar sesión','login','lock','primary')}</div>`;if(!state.works.length)return `<div class="empty">${icon('folder')}<h3>El próximo proyecto empieza aquí.</h3><p>Prepara tu archivo y confirma la entrega con “Guardar trabajos”.</p>${link('Abrir trabajos','trabajos','primary')}</div>`;return `<div class="grid-3">${[...state.works].sort((a,b)=>String(b.created).localeCompare(a.created)).slice(0,3).map(w=>`<button class="panel action" data-action="open-work" data-id="${esc(w.id)}"><span class="tile-icon">${icon('file')}</span><div class="eyebrow">UNIDAD ${w.unit} / SEMANA ${w.week}</div><h3>${esc(w.name)}</h3><p>${esc(w.day)} · ${fmtDate(w.created)}</p><span class="panel-link">Ver evidencia ${icon('arrow')}</span></button>`).join('')}</div>`;}
function profile(){const p=state.profile;return `${title('01','La persona detrás<br>de <em>cada proyecto.</em>','Una mirada a quién soy, cómo aprendo y hacia dónde quiero avanzar.')}<section class="profile-grid section"><aside class="panel profile-pass"><img src="${A.photo}" alt="Retrato de Yuber"><div class="pass-body"><span class="eyebrow">MI CARNET PERSONAL</span><h2>${esc(p.name)}</h2><p>${esc(p.career)}</p><dl class="facts"><div><dt>Universidad</dt><dd>UPLA</dd></div><div><dt>Código</dt><dd>${esc(p.code)}</dd></div><div><dt>Curso</dt><dd>Base de Datos II</dd></div><div><dt>Rol</dt><dd>Estudiante</dd></div>${p.cycle?`<div><dt>Ciclo</dt><dd>${esc(p.cycle)}</dd></div>`:''}</dl>${authenticated()&&!readOnly()?`<div class="btn-row">${button('Editar mi presentación','edit-profile','edit','small wide')}</div>`:''}</div></aside><div class="story"><article class="panel"><div class="eyebrow">MI PRESENTACIÓN</div><span class="quote-mark">“</span><div class="quote">${esc(p.purpose)}</div><p>${esc(p.bio)}</p><div class="tags"><span class="tag">Lógica</span><span class="tag">Creatividad</span><span class="tag">Aprendizaje práctico</span></div></article><div class="grid-2"><article class="panel"><div class="eyebrow">MI MOTIVACIÓN</div><h3>¿Por qué Sistemas?</h3><p>${esc(p.motivation)}</p></article><article class="panel"><div class="eyebrow">MI FORMA DE APRENDER</div><h3>Una evidencia a la vez.</h3><p>${esc(p.learning)}</p></article></div><article class="panel"><div class="eyebrow">HORIZONTE PERSONAL</div><h3>Lo que quiero construir.</h3><p>${esc(p.goal)}</p></article></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">LO QUE ESTOY EXPLORANDO</div><h2>Mi caja de herramientas.</h2></div></div><div class="grid-2"><div class="panel"><h3>Datos que tienen sentido.</h3><div class="learning">${[['database','Bases de datos','Organización y relaciones entre los datos.'],['code','SQL','Consultas y manipulación de información.'],['shield','Integridad y seguridad','Cuidar la consistencia y el acceso.']].map(([ic,n,d])=>`<div class="learning-row">${icon(ic)}<div><strong>${n}</strong><p>${d}</p></div><small>EN APRENDIZAJE</small></div>`).join('')}</div></div><div class="panel"><h3>De una idea a una solución.</h3><div class="learning">${[['globe','Desarrollo web','Interfaces para mostrar y usar información.'],['history','Versiones y mejora','Comparar entregas y corregir errores.'],['book','Comunicación técnica','Explicar procesos y documentar resultados.']].map(([ic,n,d])=>`<div class="learning-row">${icon(ic)}<div><strong>${n}</strong><p>${d}</p></div><small>EN APRENDIZAJE</small></div>`).join('')}</div></div></div></section>${world()}`;}
function university(){return `<section class="academy section"><div>${title('02','Mi formación tiene<br><em>un lugar.</em>','Universidad Peruana Los Andes · Ingeniería de Sistemas')}<p>La universidad es el espacio donde conecto fundamentos, práctica y nuevas ideas. Este portafolio reúne una parte de ese proceso: mi aprendizaje en Base de Datos II.</p><div class="btn-row"><a class="btn primary" href="https://upla.edu.pe/" target="_blank" rel="noopener noreferrer">Visitar la UPLA ${icon('arrow')}</a>${link('Mi recorrido','progreso','quiet')}</div></div><div class="emblem"><img src="${A.upla}" alt="Logo de la Universidad Peruana Los Andes"></div></section><section class="grid-3 section">${actionCard('cap','Mi universidad','Formación, comunidad y oportunidades para transformar lo aprendido en proyectos.','recursos','Acceder a recursos')}${actionCard('code','Mi carrera','Ingeniería de Sistemas: comprender problemas, organizar información y construir soluciones.','perfil','Mi motivación')}${actionCard('database','Mi curso','Base de Datos II: mi espacio para documentar evidencias y aprender de cada revisión.','trabajos','Explorar evidencias')}</section><section class="section"><div class="section-head"><div><div class="eyebrow">MI ORGANIZACIÓN DEL CURSO</div><h2>Cuatro unidades.<br>Un aprendizaje continuo.</h2></div><p>Mis entregas se organizan en cuatro semanas por unidad, con espacios para miércoles y jueves.</p></div><div class="course-grid">${units.map((t,i)=>`<button class="course-item" data-action="unit-route" data-unit="${i+1}" style="text-align:left"><strong>0${i+1}</strong><h3>${t}</h3><p>4 semanas · 8 sesiones</p><span class="panel-link">Ver unidad ${icon('arrow')}</span></button>`).join('')}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">ASÍ CONSTRUYO MI RECORRIDO</div><h2>Aprender también es un proceso.</h2></div></div><div class="timeline">${[['Comprender','Revisar los conceptos y plantear preguntas.'],['Aplicar','Resolver actividades y construir evidencias.'],['Presentar','Organizar cada trabajo y explicar el resultado.'],['Mejorar','Leer observaciones y corregir mis entregas.']].map(([n,d],i)=>`<article class="milestone"><b>0${i+1}</b><h3>${n}</h3><p>${d}</p></article>`).join('')}</div></section>`;}
function connection(){return `<div class="connection" data-connection>${icon('cloud')}<div class="connection-copy"><strong data-status-title></strong><small data-status-message></small></div>${button(authenticated()?'Actualizar':'Iniciar sesión',authenticated()?'refresh':'login',authenticated()?'refresh':'lock','small')}</div>`;}
function worksPage(){return `${title('03',state.admin?'Cada entrega,<br><em>una nueva revisión.</em>':'Mis ideas, convertidas<br>en <em>evidencias.</em>',state.admin?'Revisa los archivos, consulta versiones y registra notas y observaciones.':'Selecciona una unidad y una semana. Aquí puedes guardar, editar y presentar tus trabajos.')}<div id="admin-banner">${state.admin?`<div class="admin-bar"><div><h3>Panel de administrador</h3><p>${metrics().graded.length} evaluados · ${state.works.length-metrics().graded.length} pendientes</p></div>${button('Ver pendientes','pending-filter','check','small')}</div>`:''}</div>${connection()}<div class="toolbar"><p>Base de Datos II · Miércoles y jueves</p><div class="btn-row" style="margin:0">${button('Presentar','present','play','small quiet')}${!readOnly()?button('Subir trabajo','upload','upload','primary'):''}</div></div><div class="unit-tabs" role="group" aria-label="Unidades">${units.map((t,i)=>`<button class="${state.unit===i+1?'active':''}" data-action="unit" data-unit="${i+1}" aria-pressed="${state.unit===i+1}"><strong>Unidad 0${i+1}</strong><small class="unit-name">${t}</small></button>`).join('')}</div><div class="week-tabs" id="week-tabs" role="group" aria-label="Semanas"></div><div class="search-row"><label class="search-wrap">${icon('search')}<input id="work-search" type="search" value="${esc(state.search)}" placeholder="Buscar en esta unidad…" aria-label="Buscar trabajos"></label><select id="work-filter" aria-label="Filtrar trabajos"><option value="all">Todos</option><option value="pending">Sin evaluar</option><option value="graded">Evaluados</option><option value="featured">Destacados</option></select></div><label style="font-size:11px;color:var(--muted);display:flex;gap:8px;align-items:center;margin-bottom:23px"><input type="checkbox" id="all-weeks" ${state.allWeeks?'checked':''}> Buscar en todas las semanas de esta unidad</label><div id="work-results"></div>${notice('Seleccionar un archivo lo prepara. El botón <b>Guardar trabajos</b> confirma la entrega. Para cambiar un archivo después, usa <b>Editar</b>; su versión anterior permanece en el historial.')}`;}
function filteredWorks(){let rows=state.works.filter(w=>w.unit===state.unit&&(state.allWeeks||w.week===state.week));const q=state.search.toLowerCase().trim();if(q)rows=rows.filter(w=>(w.name+' '+(w.description||'')).toLowerCase().includes(q));if(state.filter==='pending')rows=rows.filter(w=>w.grade==null);if(state.filter==='graded')rows=rows.filter(w=>w.grade!=null);if(state.filter==='featured')rows=rows.filter(w=>w.featured);return rows;}
function renderWorks(){if(!$('#work-results'))return;$('#work-filter').value=state.filter;$('#week-tabs').innerHTML=[1,2,3,4].map(w=>{const rows=state.works.filter(x=>x.unit===state.unit&&x.week===w);const slots=new Set(rows.map(x=>x.day)).size;return `<button data-action="week" data-week="${w}" class="${state.week===w?'active':''}" aria-pressed="${state.week===w}"><strong>Semana ${w}</strong><small>${authenticated()?rows.length+(rows.length===1?' archivo':' archivos'):'Inicia sesión'}</small><div class="track"><i style="width:${slots*50}%"></i></div></button>`;}).join('');
 if(!authenticated()){$('#work-results').innerHTML=`<div class="empty">${icon('lock')}<h3>Inicia sesión para cargar tus trabajos.</h3><p>Entra con la misma cuenta del estudiante o del administrador. Tus archivos se consultan desde tu base de datos.</p>${button('Entrar a mi cuenta','login','lock','primary')}</div>`;return;}
 const rows=filteredWorks();$('#work-results').innerHTML=`<div class="deliveries">${['Miércoles','Jueves'].map(day=>`<section><div class="day-heading"><h2>${day}<span>${rows.filter(w=>w.day===day).length} ${rows.filter(w=>w.day===day).length===1?'archivo':'archivos'}</span></h2>${!readOnly()?button('Subir','upload','upload','small',`data-day="${day}"`):''}</div>${rows.filter(w=>w.day===day).map(workCard).join('')||`<div class="empty">${icon('folder')}<h3>${state.search||state.filter!=='all'?'Sin coincidencias':'Un espacio para tu siguiente idea.'}</h3><p>${state.search||state.filter!=='all'?'Prueba otro término o cambia el filtro.':'Esta sección todavía no tiene entregas. Puedes añadir archivos de hasta 20 MB.'}</p></div>`}</section>`).join('')}</div>`;}
function workCard(w){const ext=(w.name.split('.').pop()||'FILE').toUpperCase().slice(0,6);const id=esc(w.id);return `<article class="work" data-work-id="${id}"><div class="work-visual">${w.cover?`<img src="${safeImage(w.cover)}" alt="Portada del trabajo">`:`<strong>${esc(ext)}</strong>${icon('file')}`}</div><div class="work-body"><span class="work-state ${w.grade==null?'pending':''}">${w.grade==null?'Pendiente de revisión':'Evaluado'}${w.featured?' · ★ Destacado':''}</span><h3>${esc(w.name)}</h3><div class="work-meta"><span>U${w.unit} / S${w.week}</span><span>${fmtBytes(w.size)}</span><span>${fmtDate(w.created)}</span></div>${w.description?`<p>${esc(w.description)}</p>`:''}${w.grade!=null?`<div class="grade"><strong>${w.grade}<small>/20</small></strong><p>${esc(w.comment||'Sin observaciones adicionales.')}</p></div>`:''}<div class="work-actions">${button('Ver','preview','eye','',`data-id="${id}"`)}${button(state.admin?'Calificar':'Editar',state.admin?'grade':'edit',''+(state.admin?'check':'edit'),'',`data-id="${id}"`)}<button class="icon-btn" data-action="download" data-id="${id}" aria-label="Descargar ${esc(w.name)}">${icon('download')}</button><button class="icon-btn" data-action="work-menu" data-id="${id}" aria-label="Más opciones para ${esc(w.name)}">${icon('menu')}</button></div></div></article>`;}
function progress(){const m=metrics();return `${title('04','El progreso se construye<br><em>paso a paso.</em>','Mi avance se calcula por sesiones con al menos una evidencia, entre las 32 sesiones del portafolio. No representa una nota final.')}<div id="progress-content">${!authenticated()?`<div class="empty">${icon('lock')}<h3>Tu progreso empieza con tu cuenta.</h3><p>Inicia sesión para ver los indicadores de tus trabajos guardados.</p>${button('Iniciar sesión','login','lock','primary')}</div>`:`<section class="progress-grid section"><div class="panel"><div class="eyebrow">EVIDENCIAS POR SESIÓN</div><div class="progress-orb" style="--value:${m.percent}"><strong>${m.percent}%</strong><span>${m.slots} de 32 sesiones</span></div><p>Una sesión cuenta como cubierta cuando tiene al menos un archivo guardado.</p><dl class="facts"><div><dt>Trabajos</dt><dd>${state.works.length}</dd></div><div><dt>Evaluados</dt><dd>${m.graded.length}</dd></div><div><dt>Promedio de notas</dt><dd>${m.average}/20</dd></div></dl></div><div class="panel"><div class="eyebrow">MI MAPA DE APRENDIZAJE</div><h3>Unidades y sesiones</h3>${units.map((u,i)=>{const slots=new Set(state.works.filter(w=>w.unit===i+1).map(w=>`${w.week}-${w.day}`));return `<div class="progress-unit"><div class="progress-label"><strong>Unidad 0${i+1}</strong><small>${slots.size}/8 sesiones · ${Math.round(slots.size/8*100)}%</small></div><div class="track"><i style="width:${slots.size/8*100}%"></i></div><div class="session-grid">${[1,2,3,4].flatMap(w=>['Miércoles','Jueves'].map(d=>`<button class="session ${slots.has(w+'-'+d)?'done':''}" data-action="session" data-unit="${i+1}" data-week="${w}" title="Semana ${w}, ${d}: ${slots.has(w+'-'+d)?'con evidencia':'sin evidencia'}">${w}${d==='Miércoles'?'M':'J'}</button>`)).join('')}</div></div>`;}).join('')}<p style="font-size:10px;margin-top:17px">M = miércoles · J = jueves. Pulsa una sesión para abrir sus trabajos.</p></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">MI BITÁCORA</div><h2>Actividad reciente.</h2></div></div>${activity()}</section>`}</div>`;}
function activity(){const events=state.works.flatMap(w=>[{name:w.name,at:w.created,text:`Entrega guardada · Unidad ${w.unit}, semana ${w.week}`,ic:'upload',id:w.id},...(w.updated&&w.updated!==w.created?[{name:w.name,at:w.updated,text:w.graded===w.updated?'Calificación registrada':'Última actualización',ic:'history',id:w.id}]:[])]).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,12);return events.length?events.map(e=>`<div class="activity">${icon(e.ic)}<div><strong>${esc(e.name)}</strong><p>${e.text}</p><small>${fmtDate(e.at)}</small></div><button class="icon-btn" data-action="open-work" data-id="${esc(e.id)}" aria-label="Abrir trabajo">${icon('arrow')}</button></div>`).join(''):`<div class="empty"><h3>Aún no hay actividad.</h3><p>Las entregas guardadas aparecerán aquí.</p></div>`;}
function resources(){return `${title('05','Un espacio para<br><em>seguir aprendiendo.</em>','Accesos, ayuda y herramientas para organizar mejor mi portafolio.')}<section class="grid-2 section">${[['cap','Universidad Peruana Los Andes','Portal institucional de mi universidad.','https://upla.edu.pe/'],['code','Mi GitHub','Mi espacio para compartir código y proyectos.','https://github.com/quispeyuber06-tech'],['database','Documentación PostgreSQL','Referencia oficial para profundizar en bases de datos.','https://www.postgresql.org/docs/'],['cloud','Documentación Supabase','Cómo funciona el servicio que guarda mis trabajos.','https://supabase.com/docs']].map(([ic,n,d,url])=>`<a class="resource" href="${url}" target="_blank" rel="noopener noreferrer"><span class="tile-icon">${icon(ic)}</span><div><h3>${n}</h3><p>${d}</p></div>${icon('arrow')}</a>`).join('')}</section><section class="section"><div class="section-head"><div><div class="eyebrow">PREGUNTAS FRECUENTES</div><h2>Todo en su lugar.</h2></div></div><div class="faq">${[['¿Cómo guardo un trabajo?','Entra en Trabajos, elige la unidad, la semana y el día. Pulsa Subir, selecciona el archivo y luego Guardar trabajos. Espera el mensaje de confirmación antes de cerrar.'],['¿Cómo lo veo en otro dispositivo?','Abre este mismo HTML en un navegador con internet o la versión que tú subas a GitHub Pages. Inicia sesión con la misma cuenta y pulsa Actualizar. Los trabajos se consultan en Supabase.'],['¿Qué hago si me equivoqué de archivo?','Pulsa Editar en la tarjeta. Puedes cambiar el título, la descripción y seleccionar un archivo de reemplazo. Al guardar, el archivo anterior queda en Historial. La nueva versión vuelve a estar pendiente de evaluación.'],['¿Qué diferencia hay entre el HTML conectado y una copia sin conexión?','El HTML conectado consulta tu cuenta y la lista actual de trabajos. La copia sin conexión contiene los archivos que había al descargarla; sus cambios no se sincronizan automáticamente.'],['¿Por qué el administrador usa otra cuenta?','El estudiante gestiona sus entregas. La cuenta administradora consulta archivos, califica y escribe observaciones. Los permisos se verifican en la base de datos.'],['¿Cómo llevo la nueva versión a GitHub?','Descarga el HTML conectado, cambia su nombre a index.html y reemplaza el archivo de tu repositorio. Usa la misma configuración de GitHub Pages. Los trabajos continúan en el mismo proyecto de Supabase.'],['¿El asistente responde con inteligencia artificial?','El asistente es una guía integrada para navegación, guardado y consultas básicas. Sus respuestas son locales y no envía tus preguntas a otro servicio. La voz opcional es la voz en español de tu navegador.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><section class="grid-2">${actionCard('download','Tu portafolio contigo','Descarga el HTML conectado o una copia con tus trabajos para consultar sin internet.','cuenta','Ir a mi cuenta')}${actionCard('history','Recuperar entregas anteriores','Importa trabajos de una copia HTML que incluya archivos de la versión anterior.','cuenta','Ver opciones de importación')}</section>`;}
function account(){const s=cloud.getState();return `${title('06','Mi cuenta.<br><em>Mis trabajos, conmigo.</em>','Un acceso para consultar las mismas evidencias desde tu computadora, celular o tablet.')}<section class="panel section"><div class="account-heading"><img src="${A.photo}" alt="Yuber"><div><h2>${authenticated()?state.admin?'Cuenta administradora':'Mi cuenta de estudiante':'Tu portafolio te espera'}</h2><p>${esc(s.email||'Inicia sesión con tu cuenta del portafolio.')}</p></div></div>${connection()}<div class="btn-row">${authenticated()&&!offline?button('Cerrar sesión','logout','logout','quiet'):!offline?button('Iniciar sesión','login','lock','primary'):''}${authenticated()?button('Ir a mis trabajos','works','folder','primary'):''}</div></section><section class="grid-2 section"><article class="panel"><span class="tile-icon">${icon('download')}</span><h3>HTML conectado</h3><p>Tu diseño, tu foto y la conexión configurada en un solo archivo. En cada dispositivo, inicia sesión para consultar tus trabajos.</p><div class="btn-row">${button('Descargar HTML conectado','export','download','wide')}</div></article><article class="panel"><span class="tile-icon">${icon('folder')}</span><h3>Copia con mis archivos</h3><p>Incluye las entregas actuales para llevarlas en un USB y presentarlas sin internet. Es una copia del momento en que la descargas.</p><div class="btn-row">${button('Guardar copia sin conexión','backup','download','wide')}</div></article><article class="panel"><span class="tile-icon">${icon('history')}</span><h3>Recuperar una copia anterior</h3><p>Si guardaste un HTML con trabajos dentro, puedes importarlos a tu cuenta. La copia original se conserva.</p><div class="btn-row">${button('Importar trabajos','import','upload','wide')}</div></article><article class="panel"><span class="tile-icon">${icon('shield')}</span><h3>Mi acceso y privacidad</h3><p>Tu contraseña no se incluye en el HTML descargado. Las entregas requieren una cuenta autorizada en tu proyecto.</p><div class="btn-row">${link('Ayuda del portafolio','recursos','wide')}</div></article></section>${notice('Los trabajos, notas y observaciones se guardan en Supabase. La presentación personal se incluye al descargar tu HTML actualizado. Para cargar archivos y consultar cambios recientes necesitas internet.')}`;}
function notifications(){const rows=state.works.filter(w=>w.grade!=null).sort((a,b)=>(b.graded||b.updated||b.created).localeCompare(a.graded||a.updated||a.created));return `${title('07','Observaciones que<br><em>me ayudan a mejorar.</em>','Calificaciones y comentarios de mis entregas.')}<div class="toolbar"><p>${rows.filter(w=>!w.seen).length} notificaciones nuevas</p>${authenticated()&&!state.admin?button('Marcar como leídas','seen','check','small'):''}</div>${!authenticated()?`<div class="empty"><h3>Inicia sesión para ver las notificaciones.</h3>${button('Iniciar sesión','login','lock','primary')}</div>`:rows.length?rows.map(w=>`<article class="notification"><div class="eyebrow">${!w.seen?'NUEVA REVISIÓN':'REVISIÓN'} · U${w.unit} / S${w.week}</div><h3>${esc(w.name)}</h3><div class="grade"><strong>${w.grade}<small>/20</small></strong><p>${esc(w.comment||'Sin observaciones adicionales.')}</p></div><div class="btn-row">${button('Abrir trabajo','open-work','arrow','small',`data-id="${esc(w.id)}"`)}</div></article>`).join(''):`<div class="empty">${icon('bell')}<h3>Aún no hay calificaciones.</h3><p>Cuando el administrador evalúe tus trabajos, podrás leer sus observaciones aquí.</p></div>`}`;}

function safeImage(value){return /^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value||'')?value:A[state.theme];}
function updateStatus(){const s=cloud.getState();const unread=state.works.filter(w=>w.grade!=null&&!w.seen).length;const dot=$('#notify-dot');if(dot)dot.hidden=!unread;
 if($('#account-label'))$('#account-label').innerHTML=`${state.admin?'Administrador':s.role?'Yuber':'Mi cuenta'}<small>${s.role?'Sesión iniciada':'Iniciar sesión'}</small>`;
 const names={local:'Copia sin conexión',ready:'Cuenta conectada a Supabase',syncing:'Guardando en Supabase…',checking:'Comprobando tu cuenta…','signed-out':'Inicia sesión para consultar tus trabajos',offline:'Sin conexión a internet',error:'No se pudo completar la consulta'};
 $$('[data-status-title]').forEach(el=>el.textContent=names[s.phase]||'Mi cuenta');$$('[data-status-message]').forEach(el=>el.textContent=s.phase==='ready'?'Última consulta: '+new Date(s.lastSynced).toLocaleTimeString('es-PE'):s.message);
 $$('[data-stat="works"]').forEach(el=>el.textContent=authenticated()?state.works.length:'—');$$('[data-stat="progress"]').forEach(el=>el.textContent=authenticated()?metrics().percent+'%':'—');
 const fs=$('.form-status');if(fs&&state.busy)fs.textContent=['checking','syncing'].includes(s.phase)?s.message:'';
}
function syncFromCloud(){if(offline){refreshLocal();return;}const snap=cloud.getSnapshot();state.works=snap.works||[];state.admin=!!snap.admin;state.loaded=!snap.needsLogin;updateStatus();if(state.route==='trabajos')renderWorks();else if(state.route==='inicio'&&$('#recent-works'))$('#recent-works').innerHTML=recent();else if(['progreso','notificaciones','cuenta'].includes(state.route)&&!$('#dialog').open)render();}
async function refreshLocal(){try{const r=await fetch('/api/portfolio');const d=await r.json();if(!r.ok)throw Error(d.error);state.works=d.works;state.admin=d.admin;state.loaded=true;updateStatus();if(state.route==='trabajos')renderWorks();else if(state.route==='inicio'&&$('#recent-works'))$('#recent-works').innerHTML=recent();}catch(e){toast(e.message,true);}}
async function refresh(){if(!authenticated())return loginDialog();if(offline)await refreshLocal();else await cloud.refresh();toast('Lista actualizada.');}
function applyTheme(){document.documentElement.dataset.theme=state.theme;$$('[data-action="theme"]').forEach(b=>{b.classList.toggle('active',b.dataset.theme===state.theme);b.setAttribute('aria-pressed',String(b.dataset.theme===state.theme));});$$('[data-world-art]').forEach(i=>{i.src=A[state.theme];i.alt=state.theme==='jjk'?'Gojo y Yuji de Jujutsu Kaisen':'Consolas y personajes originales de videojuegos';});$$('[data-world-label]').forEach(el=>el.textContent=state.theme==='jjk'?'EDICIÓN / JUJUTSU KAISEN':'EDICIÓN / PLAYER ONE');$$('[data-world-title]').forEach(el=>el.innerHTML=state.theme==='jjk'?'Enfocar. Crear.<br>Superar mis límites.':'El siguiente nivel<br>lo construyo yo.');$$('[data-world-code]').forEach(el=>el.textContent=state.theme==='jjk'?'CURSED ENERGY / 01':'PRESS START / 02');document.body.classList.toggle('paused',state.paused);}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?9000:5500);}
let dialogCleanup=null,returnFocus=null,uploadDraft=null;
function closeDialog(){if(state.busy)return;$('#dialog').close();document.body.style.overflow='';if(dialogCleanup){dialogCleanup();dialogCleanup=null;}uploadDraft=null;if(returnFocus?.isConnected&&!$('#dialog').contains(returnFocus)&&returnFocus!==document.body&&returnFocus.getClientRects().length)returnFocus.focus({preventScroll:true});else $('#main').focus({preventScroll:true});}
function showDialog(name,body,klass=''){if($('#dialog').open){$('#dialog').close();if(dialogCleanup)dialogCleanup();dialogCleanup=null;}returnFocus=document.activeElement;const d=$('#dialog');d.className=klass;d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${name}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar ventana">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.showModal();document.body.style.overflow='hidden';}
function loginDialog(){if(offline){toast('Esta es una copia sin conexión. Abre el HTML conectado para entrar a tu cuenta.');return;}showDialog('Tu historia continúa aquí.',`<div class="login-logo"><img src="${A.upla}" alt="UPLA"><strong>bitácora<em>.</em></strong></div><p>Inicia sesión para ver tus trabajos guardados y continuar desde cualquier dispositivo.</p><form id="login-form"><div class="field"><label for="login-email">Correo de tu cuenta</label><input id="login-email" name="email" type="email" autocomplete="username" required placeholder="tu.correo@gmail.com"></div><div class="field"><label for="login-password">Contraseña</label><div class="password-wrap"><input id="login-password" name="password" type="password" autocomplete="current-password" required placeholder="Tu contraseña"><button type="button" class="icon-btn" data-action="show-password" aria-label="Mostrar contraseña">${icon('eye')}</button></div></div><p class="form-error" role="alert"></p><p class="form-status" role="status"></p><button class="btn primary wide" type="submit">${icon('lock')}Entrar a mi portafolio</button></form><button class="guest-link" data-action="guest">Explorar mi presentación</button><div class="login-footnote">${icon('shield')}Estudiante y administrador usan sus propias cuentas.</div>`,'login-dialog');}
async function api(body){const r=await fetch('/api/portfolio',{method:'POST',...(body instanceof FormData?{body}:{body:JSON.stringify(body),headers:{'Content-Type':'application/json'}})});const d=await r.json();if(!r.ok||d.error)throw Error(d.error||'No se completó el guardado.');if(offline)await refreshLocal();else syncFromCloud();return d;}
async function guarded(task){if(state.busy)return;state.busy=true;$$('#dialog button,#dialog input,#dialog select,#dialog textarea').forEach(x=>x.disabled=true);const err=$('.form-error');if(err)err.textContent='';try{return await task();}catch(e){if($('#dialog').open&&$('.form-error'))$('.form-error').textContent=e.message;else toast(e.message,true);return null;}finally{state.busy=false;$$('#dialog button,#dialog input,#dialog select,#dialog textarea').forEach(x=>x.disabled=false);}}
function requireStudent(){if(!authenticated()){loginDialog();return false;}if(state.admin){toast('Entra con la cuenta del estudiante para gestionar archivos.');return false;}return true;}
function workById(id){const w=state.works.find(w=>w.id===id);if(!w)throw Error('El trabajo cambió. Actualiza la lista y vuelve a abrirlo.');return w;}
function openUpload(id,day='Miércoles'){if(!requireStudent())return;const old=id?workById(id):null;uploadDraft={id:old?.id||crypto.randomUUID(),old,file:null};showDialog(old?'Editar trabajo':'Preparar mi entrega',`<p>${old?'Cambia el título o reemplaza el archivo. Se conservará la versión anterior.':'Elige el archivo y confirma con Guardar trabajos.'}</p><form id="upload-form">${!old?`<div class="field-row"><div class="field"><label for="upload-unit">Unidad</label><select id="upload-unit" name="unit">${[1,2,3,4].map(u=>`<option value="${u}" ${u===state.unit?'selected':''}>Unidad ${u}</option>`).join('')}</select></div><div class="field"><label for="upload-week">Semana</label><select id="upload-week" name="week">${[1,2,3,4].map(w=>`<option value="${w}" ${w===state.week?'selected':''}>Semana ${w}</option>`).join('')}</select></div></div><div class="field"><label for="upload-day">Día</label><select id="upload-day" name="day"><option ${day==='Miércoles'?'selected':''}>Miércoles</option><option ${day==='Jueves'?'selected':''}>Jueves</option></select></div>`:`<div class="notice">${icon('history')}<span>Unidad ${old.unit} · Semana ${old.week} · ${old.day}. Al editar, la entrega queda pendiente de una nueva evaluación.</span></div>`}<label class="drop" id="drop-zone">${icon('upload')}<strong>${old?'Seleccionar archivo de reemplazo (opcional)':'Seleccionar un archivo'}</strong><small>PDF, documentos, imágenes, audio o video · Máximo 20 MB</small><input type="file" id="upload-file" aria-label="Archivo del trabajo"></label><div id="staged-file"></div><div class="field"><label for="upload-title">Título del trabajo</label><input id="upload-title" name="name" maxlength="180" required value="${esc(old?.name||'')}" placeholder="Nombre de mi evidencia"></div><div class="field"><label for="upload-description">Descripción</label><textarea id="upload-description" name="description" maxlength="1000" placeholder="¿Qué desarrollaste en este trabajo?">${esc(old?.description||'')}</textarea></div><p class="form-error" role="alert"></p><p class="form-status" role="status"></p><div class="dialog-footer">${button('Cancelar','close','','quiet')}<button class="btn primary" type="submit">${icon('cloud')}${old?'Guardar cambios':'Guardar trabajos'}</button></div></form>`);$('#upload-file').addEventListener('change',e=>stageFile(e.target.files[0]));const dz=$('#drop-zone');dz.addEventListener('dragover',e=>{e.preventDefault();dz.classList.add('dragover');});dz.addEventListener('dragleave',()=>dz.classList.remove('dragover'));dz.addEventListener('drop',e=>{e.preventDefault();dz.classList.remove('dragover');stageFile(e.dataTransfer.files[0]);});}
function stageFile(file){if(!file||!uploadDraft)return;if(file.size<1||file.size>20971520){$('.form-error').textContent='Selecciona un archivo de entre 1 byte y 20 MB.';return;}uploadDraft.file=file;$('.form-error').textContent='';if(!$('#upload-title').value)$('#upload-title').value=file.name;let preview='';if(/^image\/(jpeg|png|webp|gif)$/.test(file.type)){const url=URL.createObjectURL(file);const prev=dialogCleanup;dialogCleanup=()=>{URL.revokeObjectURL(url);prev?.();};preview=`<img src="${url}" alt="Vista del archivo seleccionado">`;}$('#staged-file').innerHTML=`<div class="staged">${preview||icon('file')}<div><strong>${esc(file.name)}</strong><small>${fmtBytes(file.size)} · Preparado, aún sin guardar</small></div></div>`;}
function fileName(title,file,old){let name=title.trim();const suffix=(file?.name||old?.name||'').match(/\.[a-zA-Z0-9]{1,9}$/)?.[0]||'';const oldSuffix=old?.name?.match(/\.[a-zA-Z0-9]{1,9}$/)?.[0];if(file&&oldSuffix&&suffix!==oldSuffix&&name.endsWith(oldSuffix))name=name.slice(0,-oldSuffix.length);if(suffix&&!name.toLowerCase().endsWith(suffix.toLowerCase())&&!/\.[a-zA-Z0-9]{1,9}$/.test(name))name+=suffix;return name;}
async function saveUpload(form){const draft=uploadDraft;if(!draft)return;if(!draft.old&&!draft.file){$('.form-error').textContent='Selecciona el archivo antes de guardar.';return;}const values=new FormData(form);const fd=new FormData();fd.set('id',draft.id);fd.set('action',draft.old?'replace':'create');fd.set('name',fileName(values.get('name'),draft.file,draft.old));fd.set('description',values.get('description'));if(draft.old)fd.set('revision',String(draft.old.revision||1));else for(const k of ['unit','week','day'])fd.set(k,values.get(k));if(draft.file)fd.set('file',draft.file);const result=await guarded(async()=>{await api(fd);return true;});if(result){const old=draft.old;state.unit=old?.unit||Number(values.get('unit'));state.week=old?.week||Number(values.get('week'));closeDialog();goto('trabajos');toast(offline?'Guardado en esta copia sin conexión.':'Trabajo guardado y confirmado en Supabase.');}}
async function download(id,version){const row=await window.portfolioFile(id,version);if(!row?.file)throw Error('Archivo no disponible.');saveBlob(row.file,row.name);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),20000);}
async function preview(id,version){const w=workById(id);showDialog(esc(version===undefined?w.name:'Versión anterior'),`<p>Cargando el archivo…</p><p class="form-error" role="alert"></p>`,'wide-dialog');await guarded(async()=>{const row=await window.portfolioFile(id,version);const url=URL.createObjectURL(row.file);dialogCleanup=()=>URL.revokeObjectURL(url);const mime=(row.type||row.file.type||'').toLowerCase();let content;if(/^image\/(jpeg|png|webp|gif)$/.test(mime))content=`<img class="preview-image" src="${url}" alt="${esc(row.name)}">`;else if(mime==='application/pdf')content=`<iframe class="preview-frame" src="${url}" title="Vista del PDF" sandbox="allow-same-origin"></iframe>`;else if(mime.startsWith('video/'))content=`<video class="preview-video" src="${url}" controls playsinline></video>`;else if(mime.startsWith('audio/'))content=`<audio src="${url}" controls style="width:100%"></audio>`;else content=`<div class="empty">${icon('file')}<h3>Archivo listo para descargar.</h3><p>Este formato se abre con su aplicación correspondiente.</p></div>`;$('.dialog-body').innerHTML=`${content}<div class="dialog-footer">${button('Descargar archivo','download','download','primary',`data-id="${esc(id)}" ${version!==undefined?`data-version="${version}"`:''}`)}</div><p class="form-error" role="alert"></p>`;});}
function workMenu(id){const w=workById(id);showDialog('Opciones del trabajo',`<p>${esc(w.name)}</p><div class="learning">${button('Ver historial de versiones','history','history','wide',`data-id="${esc(id)}"`)}${!state.admin?`${button(w.featured?'Quitar de destacados':'Destacar trabajo','feature','star','wide',`data-id="${esc(id)}"`)}${button('Cambiar portada','cover','eye','wide',`data-id="${esc(id)}"`)}${button('Eliminar trabajo','delete','trash','wide danger',`data-id="${esc(id)}"`)}`:''}</div><p class="form-error" role="alert"></p>`);}
function history(id){const w=workById(id);showDialog('Historial de versiones',`<p>La versión actual se mantiene hasta que confirmes una restauración.</p><div style="margin-top:20px">${(w.history||[]).length?w.history.map((h,i)=>`<div class="history-item"><strong>Versión ${i+1} · ${esc(h.name)}</strong><p>${fmtDate(h.updated||h.created)} · ${fmtBytes(h.size)}</p><div class="btn-row">${button('Ver','preview','eye','small',`data-id="${esc(id)}" data-version="${i}"`)}${button('Descargar','download','download','small',`data-id="${esc(id)}" data-version="${i}"`)}${!state.admin?button('Restaurar','restore','history','small',`data-id="${esc(id)}" data-version="${i}"`):''}</div></div>`).reverse().join(''):`<div class="empty"><h3>Esta entrega aún no tiene versiones anteriores.</h3><p>Se creará una versión cuando edites el trabajo.</p></div>`}</div><p class="form-error" role="alert"></p>`);}
function gradeDialog(id){if(!state.admin)return;const w=workById(id);showDialog('Evaluar trabajo',`<p>${esc(w.name)} · U${w.unit} / S${w.week}</p><form id="grade-form" data-id="${esc(id)}" data-revision="${w.revision||1}"><div class="field"><label for="grade-value">Nota (de 0 a 20)</label><input type="number" min="0" max="20" step="1" id="grade-value" name="grade" required value="${w.grade??''}"></div><div class="field"><label for="grade-comment">Observaciones para el estudiante</label><textarea id="grade-comment" name="comment" maxlength="2000">${esc(w.comment||'')}</textarea></div><p class="form-error" role="alert"></p><p class="form-status" role="status"></p><div class="dialog-footer">${button('Cancelar','close','','quiet')}<button type="submit" class="btn primary">${icon('check')}Guardar evaluación</button></div></form>`);}
function editProfile(){if(!requireStudent())return;const fields=[['name','Mi nombre',80],['code','Código',30],['cycle','Ciclo (opcional)',30],['purpose','Mi propósito',220],['bio','Mi presentación',1000],['motivation','Por qué elegí mi carrera',500],['learning','Cómo aprendo',500],['goal','Mi objetivo',500]];showDialog('Editar mi presentación',`<p>Personaliza los textos con tu propia historia. Después descarga el HTML actualizado para llevar estos cambios contigo.</p><form id="profile-form">${fields.map(([key,label,max])=>`<div class="field"><label for="profile-${key}">${label}</label>${max>220?`<textarea id="profile-${key}" name="${key}" maxlength="${max}">${esc(state.profile[key])}</textarea>`:`<input id="profile-${key}" name="${key}" maxlength="${max}" value="${esc(state.profile[key])}" ${key==='name'?'required':''}>`}</div>`).join('')}<div class="dialog-footer">${button('Cancelar','close','','quiet')}<button type="submit" class="btn primary">Guardar presentación</button></div></form>`);}
async function exportHTML(withFiles=false){if(withFiles&&!authenticated())return loginDialog();showDialog(withFiles?'Preparando copia con tus trabajos':'Preparando tu HTML',`<p>Estamos preparando el archivo descargable.</p><p class="form-status" role="status"></p><p class="form-error" role="alert"></p>`);const success=await guarded(async()=>{let snapshot={works:[]};if(withFiles){const rows=await window.portfolioGetAll();const encode=async w=>{const bytes=new Uint8Array(await w.file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const {file,history,...rest}=w;return {...rest,bytes:btoa(binary),history:await Promise.all((history||[]).map(encode))};};snapshot={works:await Promise.all(rows.map(encode)),mode:'offline',copyId:crypto.randomUUID()};}
 const replaceJson=(html,id,obj)=>html.replace(new RegExp('(<script[^>]*id="'+id+'"[^>]*>)[\\s\\S]*?(<\\/script>)'),(_,start,end)=>start+JSON.stringify(obj).replace(/</g,'\\u003c')+end);
 let html=replaceJson(pristine,'portfolio-snapshot',snapshot);html=replaceJson(html,'portfolio-presentation',state.profile);html=replaceJson(html,'portfolio-cloud-config',withFiles?{enabled:false}:JSON.parse(document.getElementById('portfolio-cloud-config').textContent));html=html.replace(/<html lang="es" data-theme="[^"]+"/,`<html lang="es" data-theme="${state.theme}"`);saveBlob(new Blob([html],{type:'text/html;charset=utf-8'}),withFiles?'Portafolio-Yuber-Copia-con-trabajos.html':'Portafolio-BD2-Profesional.html');return true;});if(success){closeDialog();toast(withFiles?'Copia preparada. Guarda el archivo descargado.':'HTML conectado preparado para descargar.');}}
function importDialog(){if(!requireStudent())return;if(offline){toast('Abre el HTML conectado e inicia sesión para importar a Supabase.');return;}showDialog('Recuperar trabajos anteriores',`<p>Elige una copia HTML que incluya tus archivos. También puedes buscar trabajos locales en este navegador.</p><div class="field"><label for="import-file">Copia HTML</label><input type="file" accept=".html,text/html" id="import-file"></div><div class="btn-row">${button('Buscar en este navegador','import-local','history','small')}</div><p id="import-count" class="form-status"></p><p class="form-error" role="alert"></p><div class="dialog-footer">${button('Cancelar','close','','quiet')}${button('Importar a mi cuenta','import-confirm','cloud','primary','disabled id="import-confirm"')}</div>`);$('#import-file').onchange=async e=>{if(!e.target.files[0])return;const count=await guarded(()=>cloud.selectImportFile(e.target.files[0]));if(count!==null){$('#import-count').textContent=count+' trabajos encontrados. Las notas locales requieren revisión del administrador.';$('#import-confirm').disabled=count===0;}};}
let presentationList=[],presentationIndex=0;
function present(){if(!authenticated())return loginDialog();presentationList=filteredWorks();if(!presentationList.length){toast('No hay trabajos en la selección actual para presentar.');return;}presentationIndex=0;showPresentation();}
function showPresentation(){const w=presentationList[presentationIndex];showDialog('Mis evidencias · '+(presentationIndex+1)+' / '+presentationList.length,`<div class="eyebrow">UNIDAD ${w.unit} / SEMANA ${w.week} / ${w.day}</div><h2 style="margin:20px 0;font-size:32px">${esc(w.name)}</h2><p style="white-space:pre-wrap">${esc(w.description||'Evidencia de aprendizaje de Base de Datos II.')}</p>${w.grade!=null?`<div class="grade"><strong>${w.grade}<small>/20</small></strong><p>${esc(w.comment)}</p></div>`:''}<div class="btn-row">${button('Abrir archivo','preview','eye','primary',`data-id="${esc(w.id)}"`)}${button('Descargar','download','download','quiet',`data-id="${esc(w.id)}"`)}</div><div class="dialog-footer">${button('Anterior','present-prev','','small',presentationIndex===0?'disabled':'')}${button('Siguiente','present-next','right','small',presentationIndex===presentationList.length-1?'disabled':'')}</div><p class="form-error" role="alert"></p>`,'wide-dialog');}

function bot(){const root=$('#bot-root');root.innerHTML=`<button class="bot-button" data-action="bot" aria-label="Abrir asistente del portafolio" aria-expanded="false"><img src="${A.bot}" alt="Luffy, asistente del portafolio"></button><section class="bot-panel" hidden aria-label="Asistente del portafolio"><div class="bot-head"><img src="${A.bot}" alt=""><div><strong>Tu compañero de bitácora</strong><small>Guía local del portafolio</small></div><button class="icon-btn" data-action="bot" aria-label="Cerrar asistente">${icon('close')}</button></div><div class="bot-log" role="log" aria-live="polite"></div><div class="bot-suggestions">${['Guardar trabajo','Mi progreso','Mis notas','Salta'].map(t=>`<button data-action="bot-ask" data-text="${t}">${t}</button>`).join('')}</div><form class="bot-form" id="bot-form"><input id="bot-input" aria-label="Mensaje para el asistente" placeholder="¿En qué te ayudo?" maxlength="500"><button type="submit" class="icon-btn" aria-label="Enviar mensaje">${icon('send')}</button></form><label class="bot-voice"><input id="bot-voice" type="checkbox">Leer respuestas con la voz del navegador</label></section>`;addMessage('¡Hola, Yuber! Puedo ayudarte a guardar un trabajo, ver tus notas o recorrer tu portafolio. ¿Qué hacemos hoy?');}
function addMessage(text,user=false){const el=document.createElement('div');el.className='bot-message'+(user?' user':'');el.textContent=text;$('.bot-log').append(el);$('.bot-log').scrollTop=$('.bot-log').scrollHeight;}
function askBot(text){if(!text.trim())return;addMessage(text,true);const q=text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');let answer;
 if(/guardar|subir|trabajo|archivo/.test(q)){answer='Abre Trabajos, elige unidad y semana, pulsa Subir y selecciona tu archivo. Después pulsa Guardar trabajos y espera la confirmación de Supabase. Puedo abrir esa página por ti.';goto('trabajos');}
 else if(/progreso|avance/.test(q)){const m=metrics();answer=authenticated()?`Tienes ${state.works.length} ${state.works.length===1?'trabajo guardado':'trabajos guardados'} y evidencias en ${m.slots} de 32 sesiones (${m.percent} %). ¡Seguimos construyendo!`:'Inicia sesión para consultar tu progreso real. Puedes hacerlo desde Mi cuenta.';}
 else if(/nota|calificacion/.test(q)){const m=metrics();answer=authenticated()?m.graded.length?`Tienes ${m.graded.length} trabajos evaluados. El promedio de esas notas es ${m.average}/20. Revisa las observaciones en Notificaciones.`:'Aún no tienes trabajos evaluados. Las revisiones aparecerán en Notificaciones.':'Primero inicia sesión para consultar tus notas.';}
 else if(/salta|saltar|hola|luffy/.test(q)){answer='¡Vamos por la siguiente aventura, Yuber! Una idea, una prueba, una mejora.';$('.bot-button').animate([{transform:'translateY(0) rotate(0)'},{transform:'translateY(-30px) rotate(-12deg)'},{transform:'translateY(0) rotate(0)'}],{duration:650,easing:'ease-out'});}
 else if(/sql|consulta/.test(q))answer='Una consulta SQL básica es: SELECT columnas FROM tabla WHERE condición;. SELECT elige las columnas, FROM indica la tabla y WHERE filtra las filas.';
 else if(/universidad|upla/.test(q)){answer='Tu universidad es la Universidad Peruana Los Andes y tu carrera es Ingeniería de Sistemas. Abrí tu página de Universidad.';goto('universidad');}
 else if(/editar|cambiar/.test(q))answer='En la tarjeta del trabajo, pulsa Editar. Puedes cambiar el título, la descripción o reemplazar el archivo. Luego pulsa Guardar cambios. La versión anterior queda en el historial.';
 else answer='Soy una guía local: puedo explicar cómo guardar o editar trabajos, mostrar tu avance y tus notas, o abrir Universidad. Prueba “mi progreso” o “guardar trabajo”.';
 addMessage(answer);if($('#bot-voice').checked&&'speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(answer);u.lang='es-PE';u.voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('es'))||null;u.rate=1.04;speechSynthesis.speak(u);}}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;const version=el.dataset.version===undefined?undefined:Number(el.dataset.version);try{
 if(a==='menu'){$('.nav').classList.toggle('open');el.setAttribute('aria-expanded',String($('.nav').classList.contains('open')));}
 else if(a==='theme'||a==='swap-theme'){state.theme=a==='theme'?el.dataset.theme:state.theme==='jjk'?'game':'jjk';safeSet('yuber-theme-v2',state.theme);applyTheme();}
 else if(a==='motion'){state.paused=!state.paused;safeSet('yuber-paused',state.paused);applyTheme();$('#motion-label')?.replaceChildren(document.createTextNode((state.paused?'Reanudar':'Pausar')+' animaciones'));el.textContent=(state.paused?'Reanudar':'Pausar')+' animaciones';}
 else if(a==='close'||a==='guest'){if(a==='guest')state.guest=true;closeDialog();}
 else if(a==='login')loginDialog();
 else if(a==='show-password'){const inp=$('#login-password');inp.type=inp.type==='password'?'text':'password';el.setAttribute('aria-label',inp.type==='password'?'Mostrar contraseña':'Ocultar contraseña');}
 else if(a==='account')goto('cuenta');
 else if(a==='notifications')goto('notificaciones');
 else if(a==='works')goto('trabajos');
 else if(a==='refresh')await guarded(refresh);
 else if(a==='logout'){await guarded(()=>cloud.logout());state.works=[];state.admin=false;render();loginDialog();}
 else if(a==='unit'){state.unit=Number(el.dataset.unit);state.week=1;render();}
 else if(a==='week'){state.week=Number(el.dataset.week);renderWorks();}
 else if(a==='unit-route'||a==='session'){state.unit=Number(el.dataset.unit);state.week=Number(el.dataset.week||1);state.allWeeks=false;goto('trabajos');}
 else if(a==='pending-filter'){state.filter='pending';state.allWeeks=true;render();}
 else if(a==='open-work'){const w=workById(id);state.unit=w.unit;state.week=w.week;state.filter='all';state.search='';state.allWeeks=false;goto('trabajos');setTimeout(()=>document.querySelector(`[data-work-id="${CSS.escape(id)}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}),100);}
 else if(a==='upload')openUpload(null,el.dataset.day||'Miércoles');
 else if(a==='edit')openUpload(id);
 else if(a==='preview')await preview(id,version);
 else if(a==='download')await guarded(()=>download(id,version));
 else if(a==='work-menu')workMenu(id);
 else if(a==='history')history(id);
 else if(a==='grade')gradeDialog(id);
 else if(a==='feature'){const ok=await guarded(()=>api({action:'feature',id}));if(ok){closeDialog();renderWorks();toast('Destacado actualizado.');}}
 else if(a==='delete'){showDialog('Eliminar este trabajo',`<p>Se eliminará <b>${esc(workById(id).name)}</b> junto con sus versiones guardadas.</p><div class="dialog-footer">${button('Conservar','close','','quiet')}${button('Eliminar trabajo','delete-confirm','trash','danger',`data-id="${esc(id)}"`)}</div><p class="form-error" role="alert"></p>`);}
 else if(a==='delete-confirm'){const ok=await guarded(()=>api({action:'delete',id}));if(ok){closeDialog();renderWorks();toast(ok.warning||'Trabajo eliminado.');}}
 else if(a==='restore'){showDialog('Restaurar esta versión',`<p>La versión seleccionada pasará a ser la actual. El archivo de ahora también se conservará en el historial y la entrega volverá a evaluación.</p><div class="dialog-footer">${button('Cancelar','close','','quiet')}${button('Restaurar versión','restore-confirm','history','primary',`data-id="${esc(id)}" data-version="${version}"`)}</div><p class="form-error" role="alert"></p>`);}
 else if(a==='restore-confirm'){const ok=await guarded(()=>api({action:'restore',id,version}));if(ok){closeDialog();renderWorks();toast('Versión restaurada.');}}
 else if(a==='cover'){showDialog('Portada del trabajo',`<p>Selecciona una imagen PNG, JPEG o WebP de hasta 2 MB.</p><div class="field"><label for="cover-file">Imagen de portada</label><input id="cover-file" type="file" accept="image/png,image/jpeg,image/webp"></div><p class="form-error" role="alert"></p>`);$('#cover-file').onchange=async ev=>{const f=ev.target.files[0];if(!f)return;if(f.size>2*1024*1024||!/^image\/(png|jpeg|webp)$/.test(f.type)){$('.form-error').textContent='Usa PNG, JPEG o WebP de máximo 2 MB.';return;}const cover=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});const ok=await guarded(()=>api({action:'cover',id,cover}));if(ok){closeDialog();renderWorks();toast('Portada guardada.');}};}
 else if(a==='edit-profile')editProfile();
 else if(a==='export')await exportHTML();
 else if(a==='backup')await exportHTML(true);
 else if(a==='import')importDialog();
 else if(a==='import-local'){const count=await cloud.selectLocal();$('#import-count').textContent=count+' trabajos encontrados en este navegador.';$('#import-confirm').disabled=count===0;}
 else if(a==='import-confirm'){const ok=await guarded(()=>cloud.importLocal());if(ok){closeDialog();syncFromCloud();goto('trabajos');toast(`Importación terminada: ${ok.copied} nuevos, ${ok.skipped} ya estaban guardados.`);}}
 else if(a==='seen'){const ok=await guarded(()=>api({action:'seen'}));if(ok){render();toast('Notificaciones marcadas como leídas.');}}
 else if(a==='present')present();
 else if(a==='present-prev'){presentationIndex--;showPresentation();}
 else if(a==='present-next'){presentationIndex++;showPresentation();}
 else if(a==='bot'){const p=$('.bot-panel');p.hidden=!p.hidden;$('.bot-button').setAttribute('aria-expanded',String(!p.hidden));if(!p.hidden)$('#bot-input').focus();else if('speechSynthesis' in window)speechSynthesis.cancel();}
 else if(a==='bot-ask')askBot(el.dataset.text);
 }catch(error){toast(error.message,true);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='login-form'){const values=new FormData(f);const ok=await guarded(async()=>{await cloud.login(values.get('email'),values.get('password'));return true;});if(ok){$('#login-password').value='';syncFromCloud();closeDialog();render();toast(`Sesión iniciada. ${state.works.length} ${state.works.length===1?'trabajo consultado':'trabajos consultados'}.`);}}
 else if(f.id==='upload-form')await saveUpload(f);
 else if(f.id==='grade-form'){const values=new FormData(f);const ok=await guarded(()=>api({action:'grade',id:f.dataset.id,revision:Number(f.dataset.revision),grade:Number(values.get('grade')),comment:values.get('comment')}));if(ok){closeDialog();render();toast('Evaluación guardada en Supabase.');}}
 else if(f.id==='profile-form'){state.profile={...state.profile,...Object.fromEntries(new FormData(f))};safeSet('yuber-presentation-v2',state.profile);closeDialog();render();toast('Presentación guardada. Descarga el HTML para llevar estos textos contigo.');}
 else if(f.id==='bot-form'){const text=$('#bot-input').value;$('#bot-input').value='';askBot(text);}});
document.addEventListener('input',e=>{if(e.target.id==='work-search'){state.search=e.target.value;renderWorks();}});
document.addEventListener('change',e=>{if(e.target.id==='work-filter'){state.filter=e.target.value;renderWorks();}else if(e.target.id==='all-weeks'){state.allWeeks=e.target.checked;renderWorks();}else if(e.target.id==='bot-voice'&&!e.target.checked&&'speechSynthesis' in window)speechSynthesis.cancel();});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
window.addEventListener('hashchange',()=>{state.route=location.hash.slice(1)||'inicio';$('.nav')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false');render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('portfolio-cloud-state',updateStatus);
window.addEventListener('portfolio-refresh',syncFromCloud);
window.addEventListener('beforeunload',e=>{if(state.busy||uploadDraft?.file){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(!offline&&authenticated()&&!state.busy&&!document.hidden)cloud.refresh().catch(()=>{});},60000);
function particles(){const canvas=$('#particles'),ctx=canvas.getContext('2d');if(!ctx)return;let w=innerWidth,h=innerHeight;const resize=()=>{w=innerWidth;h=innerHeight;canvas.width=w;canvas.height=h;};resize();window.addEventListener('resize',resize);const pts=Array.from({length:32},()=>({x:Math.random(),y:Math.random(),s:Math.random()*1.4+.5,speed:Math.random()*.000018+.000009}));let last=0;function draw(t){requestAnimationFrame(draw);if(document.hidden||state.paused||matchMedia('(prefers-reduced-motion: reduce)').matches||t-last<45)return;last=t;ctx.clearRect(0,0,w,h);ctx.fillStyle=state.theme==='jjk'?'#a897ee':'#a5d364';for(const p of pts){p.y-=p.speed*45;if(p.y<0)p.y=1;ctx.beginPath();if(state.theme==='jjk')ctx.arc(p.x*w,p.y*h,p.s,0,Math.PI*2);else ctx.rect(p.x*w,p.y*h,p.s*2,p.s*2);ctx.fill();}}requestAnimationFrame(draw);}
frame();state.route=location.hash.slice(1)||'inicio';render();bot();particles();if(offline){refreshLocal();toast('Copia sin conexión: los cambios aquí no se sincronizan automáticamente.');}else setTimeout(loginDialog,180);
